import{_ as e,a as i,b as t,c as r}from"./chunks/promotion-dates-limits.B9Si78dH.js";import{_ as n,c as a,o as s,ae as l}from"./chunks/framework.DBgX5bsf.js";const P=JSON.parse('{"title":"Configuring Promotions in Drupal Commerce","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/commerce/promotions.md","filePath":"en/docs/commerce/promotions.md"}'),m={name:"en/docs/commerce/promotions.md"};function c(u,o,p,g,d,f){return s(),a("div",null,o[0]||(o[0]=[l('<h1 id="configuring-promotions-in-drupal-commerce" tabindex="-1">Configuring Promotions in Drupal Commerce <a class="header-anchor" href="#configuring-promotions-in-drupal-commerce" aria-label="Permalink to &quot;Configuring Promotions in Drupal Commerce&quot;">​</a></h1><p>Promotions are an excellent way to attract new customers and retain existing ones. With Drupal Commerce, you can configure discounts, gifts, or free shipping to boost your sales. This guide explains how to set up these promotional mechanisms.</p><h2 id="⚙️-configuring-promotions" tabindex="-1">⚙️ Configuring Promotions <a class="header-anchor" href="#⚙️-configuring-promotions" aria-label="Permalink to &quot;⚙️ Configuring Promotions&quot;">​</a></h2><h3 id="_1-access-the-promotions-interface" tabindex="-1">1. Access the Promotions Interface <a class="header-anchor" href="#_1-access-the-promotions-interface" aria-label="Permalink to &quot;1. Access the Promotions Interface&quot;">​</a></h3><ul><li>Navigate to the back office: <code>Administration &gt; Commerce &gt; Promotions</code>.</li><li>Click on <strong>Add Promotion</strong>. <img src="'+e+'" alt="Add a promotion"></li></ul><h3 id="_2-create-a-new-promotion" tabindex="-1">2. Create a New Promotion <a class="header-anchor" href="#_2-create-a-new-promotion" aria-label="Permalink to &quot;2. Create a New Promotion&quot;">​</a></h3><ul><li><strong>Name</strong>: Give a clear title (e.g., &quot;Summer 2025 Discount&quot;).</li><li><strong>Status</strong>: Activate the promotion.</li><li><strong>Offer Type</strong>: Select the type of promotion: <ul><li><em>Discount</em>: Percentage or fixed amount.</li><li><em>Gift</em>: Offer a specific product.</li><li><em>Shipping</em>: Exempt from shipping fees.</li><li>...</li></ul></li></ul><p><img src="'+i+'" alt="Offer type"></p><h3 id="_3-define-application-conditions" tabindex="-1">3. Define Application Conditions <a class="header-anchor" href="#_3-define-application-conditions" aria-label="Permalink to &quot;3. Define Application Conditions&quot;">​</a></h3><ul><li>In the <strong>Conditions</strong> tab, add rules to trigger the promotion: <ul><li><strong>Minimum Cart Amount</strong> (e.g., €50).</li><li><strong>Product Category</strong> (e.g., apply to sports items).</li><li><strong>Customer Segment</strong> (e.g., registered users).</li><li>...</li></ul></li></ul><p><img src="'+t+'" alt="Conditions"></p><h3 id="_4-configure-dates-and-limits" tabindex="-1">4. Configure Dates and Limits <a class="header-anchor" href="#_4-configure-dates-and-limits" aria-label="Permalink to &quot;4. Configure Dates and Limits&quot;">​</a></h3><ul><li><strong>Validity Period</strong>: Define a start/end date.</li><li><strong>Usage Limits</strong>: <ul><li>Maximum number of uses per customer.</li><li>Unique promo code (optional).</li></ul></li></ul><p><img src="'+r+'" alt="Dates and limits"></p><h2 id="💡-best-practices" tabindex="-1">💡 Best Practices <a class="header-anchor" href="#💡-best-practices" aria-label="Permalink to &quot;💡 Best Practices&quot;">​</a></h2><ul><li><strong>Test Promotions</strong>: Verify with test orders before launching.</li><li><strong>Combination of Promotions</strong>: Control whether promotions are combinable.</li><li><strong>Analyze Impact</strong>: Use reporting tools to measure effectiveness.</li></ul>',16)]))}const C=n(m,[["render",c]]);export{P as __pageData,C as default};
